#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int longestSubarrayDivKWithOneNegation(std::vector<int>& nums, int k) {
        int n = nums.size();
        int max_len = 0;

        for (int l = 0; l < n; ++l) {
            long long curr_sum = 0;
            for (int r = l; r < n; ++r) {
                curr_sum += nums[r];
                if ((curr_sum % k + k) % k == 0) {
                    max_len = std::max(max_len, r - l + 1);
                } else {
                    for (int m = l; m <= r; ++m) {
                        if (((curr_sum - 2LL * nums[m]) % k + k) % k == 0) {
                            max_len = std::max(max_len, r - l + 1);
                            break;
                        }
                    }
                }
            }
        }
        return max_len;
    }
};

class Solution {
    public int longestSubarrayDivKWithOneNegation(int[] nums, int k) {
        int n = nums.length;
        int maxLen = 0;

        for (int l = 0; l < n; l++) {
            long currSum = 0;
            for (int r = l; r < n; r++) {
                currSum += nums[r];
                if ((currSum % k + k) % k == 0) {
                    maxLen = Math.max(maxLen, r - l + 1);
                } else {
                    for (int m = l; m <= r; m++) {
